const raw = $input.first().json;
// SEC-3: verify token (gọi nội bộ vẫn phải kèm token)
const expected = $env.ANSER_WEBHOOK_TOKEN || '';
if (expected && ((raw.headers || {})['x-anser-token'] || '') !== expected) {
  return [{ json: { valid: false, error: 'Unauthorized' } }];
}
const b = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const channel = (b.channel || 'discord').toLowerCase();
// Abstraction: map channel -> URL từ $env (dev trỏ mock; prod đổi .env)
const MAP = {
  discord:  $env.DISCORD_WEBHOOK_URL,
  telegram: $env.TELEGRAM_WEBHOOK_URL || $env.DISCORD_WEBHOOK_URL,
  zalo:     $env.ZALO_WEBHOOK_URL     || $env.DISCORD_WEBHOOK_URL,
  facebook: $env.FB_POST_URL          || $env.DISCORD_WEBHOOK_URL
};
let target = MAP[channel] || MAP.discord;
let body_json;
if (channel === 'telegram' && $env.TELEGRAM_BOT_TOKEN && $env.TELEGRAM_CHAT_ID) {
  // Telegram Bot API THẬT — payload sendMessage khác hẳn Discord embed
  target = 'https://api.telegram.org/bot' + $env.TELEGRAM_BOT_TOKEN + '/sendMessage';
  const lines = ['*' + (b.title || 'ANSER') + '*', b.description || '',
                 ...((b.fields || []).map(f => f.name + ': ' + f.value))].filter(Boolean);
  body_json = JSON.stringify({ chat_id: $env.TELEGRAM_CHAT_ID, text: lines.join('\n'), parse_mode: 'Markdown' });
} else {
  const embed = { title: b.title || 'ANSER', color: b.color || 3447003, description: b.description || '', fields: b.fields || [], footer: { text: 'ANSER Notify • ' + channel }, timestamp: new Date().toISOString() };
  body_json = JSON.stringify({ channel, embeds: [embed] });
}
return [{ json: { valid: true, channel, target_url: target, body_json } }];
